import{_ as p,a0 as u,w as l,s as o,ao as i,I as s,x as t,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在Ubuntu中安裝XScreenSaver | LCTT x X-CMD","titleTemplate":false,"description":"在Ubuntu中安裝XScreenSaver | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Ubuntu中安裝XScreenSaver | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Ubuntu中安裝XScreenSaver | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Installing XScreenSaver In Ubuntu","title":"在Ubuntu中安裝XScreenSaver","tag":"201310","desc":""},"relativePath":"201310/Installing XScreenSaver In Ubuntu.md","filePath":"[post].md"}'),d={name:"201310/Installing XScreenSaver In Ubuntu.md"};function m(S,e,g,v,x,T){const n=u("Link");return l(),o("div",null,[e[14]||(e[14]=i('<h1 id="在ubuntu中安裝xscreensaver" tabindex="-1">在Ubuntu中安裝XScreenSaver <a class="header-anchor" href="#在ubuntu中安裝xscreensaver" aria-label="Permalink to “在Ubuntu中安裝XScreenSaver”">​</a></h1><p>這個教程將會給你展示如何在Ubuntu 12.04(也包含其他Ubuntu版本)中加入屏幕保護，它們原本不包含X-windows屏幕保護程序。不過，一些對計算機或linux不熟悉的人，並不瞭解屏幕保護。到底屏幕保護能做什麼呢?</p><p>屏幕保護是一個主要用於安全用途的計算機程序（譯註：和最初屏幕保護的用途不同了）。當計算機空閒時，這個程序會清空屏幕或者在屏幕上填滿移動的圖片或圖樣。屏幕保護也可以用於娛樂或顯示系統信息。當你打算離開辦公室又不想讓任何人看你電腦上的信息時，屏保程序將是絕佳的解決方案。</p><p>###屏幕保護怎麼讓我的電腦變得更安全？</p><p>屏幕保護能配置成在允許用户繼續工作之前要求用户輸入密碼。但是請留意，如果設置為在啓動機器後自動登入帳號，那麼攻擊者可以輕易的重啓機器來登入你的帳號。</p><p>###怎麼安裝屏幕保護？</p><p>打開一個新的終端(ctrl+alt+T)，如圖一所示。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/screen1.png" alt=""> 圖一</p><p>在安裝一個新的屏幕保護之前我們必須卸載默認屏幕保護，運行 &#39;sudo apt-get remove gnome-screensaver&#39; ，見圖二。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/screen4.png" alt=""> 圖二</p><p>用下列命令安裝XScreenSaver和一些附加的屏保包。 sudo apt-get install xscreensaver xscreensaver-data-extra xscreensaver-gl-extra</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/screen6.png" alt=""> 圖三</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/screen7.png" alt=""> 圖四</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/screen9.png" alt=""> 圖五</p>',14)),s("p",null,[e[1]||(e[1]=t("XScreenSaver 每次啓動後會隨機選擇一個屏幕保護.預瞭解如何配置XScreenSaver，參見",-1)),r(n,{href:"http://www.jwz.org/xscreensaver/faq.html"},{default:a(()=>[...e[0]||(e[0]=[t("這裏",-1)])]),_:1}),e[2]||(e[2]=t("。",-1))]),e[15]||(e[15]=s("hr",null,null,-1)),s("p",null,[e[4]||(e[4]=t("via: ",-1)),r(n,{href:"http://www.unixmen.com/installing-xscreensaver-ubuntu/"},{default:a(()=>[...e[3]||(e[3]=[t("http://www.unixmen.com/installing-xscreensaver-ubuntu/",-1)])]),_:1})]),s("p",null,[e[7]||(e[7]=t("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[5]||(e[5]=[t("LCTT",-1)])]),_:1}),e[8]||(e[8]=t(" 原創翻譯，",-1)),r(n,{href:"http://linux.cn/"},{default:a(()=>[...e[6]||(e[6]=[t("Linux中國",-1)])]),_:1}),e[9]||(e[9]=t(" 榮譽推出",-1))]),s("p",null,[e[12]||(e[12]=t("譯者：",-1)),r(n,{href:"https://github.com/Luoxcat"},{default:a(()=>[...e[10]||(e[10]=[t("Luoxcat",-1)])]),_:1}),e[13]||(e[13]=t(" 校對：",-1)),r(n,{href:"https://github.com/jasminepeng"},{default:a(()=>[...e[11]||(e[11]=[t("jasminepeng",-1)])]),_:1})])])}const X=p(d,[["render",m]]);export{w as __pageData,X as default};
